import logging
from collections.abc import Callable

import pytest


def wrapped(job: Callable[[], str]) -> str:
    """Call job exactly once and return "start:" + its result + ":end".

    The helper performs no I/O of its own: it prints and logs nothing.
    Any exception raised by job propagates unchanged.
    """
    return "start:" + job() + ":end"


def test_wraps_result() -> None:
    assert wrapped(lambda: "x") == "start:x:end"


def test_empty_result() -> None:
    assert wrapped(lambda: "") == "start::end"


def test_result_with_special_content() -> None:
    assert wrapped(lambda: "a:b\nstart:") == "start:a:b\nstart::end"


def test_job_called_exactly_once() -> None:
    calls: list[int] = []

    def job() -> str:
        calls.append(1)
        return "r"

    assert wrapped(job) == "start:r:end"
    assert len(calls) == 1


def test_job_not_called_before_wrapped() -> None:
    calls: list[int] = []

    def job() -> str:
        calls.append(1)
        return "r"

    assert calls == []
    wrapped(job)
    assert calls == [1]


def test_exception_propagates() -> None:
    class Boom(Exception):
        pass

    def job() -> str:
        raise Boom("bad")

    with pytest.raises(Boom, match="bad"):
        wrapped(job)


def test_helper_prints_nothing(capsys: pytest.CaptureFixture[str]) -> None:
    assert wrapped(lambda: "quiet") == "start:quiet:end"
    captured = capsys.readouterr()
    assert captured.out == ""
    assert captured.err == ""


def test_only_job_output_is_visible(capsys: pytest.CaptureFixture[str]) -> None:
    def job() -> str:
        print("from job")
        return "v"

    assert wrapped(job) == "start:v:end"
    captured = capsys.readouterr()
    assert captured.out == "from job\n"
    assert captured.err == ""


def test_helper_logs_nothing(caplog: pytest.LogCaptureFixture) -> None:
    with caplog.at_level(logging.DEBUG):
        assert wrapped(lambda: "v") == "start:v:end"
    assert caplog.records == []


def test_job_logging_is_not_suppressed(caplog: pytest.LogCaptureFixture) -> None:
    logger = logging.getLogger("job")

    def job() -> str:
        logger.warning("job log")
        return "v"

    with caplog.at_level(logging.DEBUG):
        assert wrapped(job) == "start:v:end"
    assert [r.getMessage() for r in caplog.records] == ["job log"]


def test_job_can_use_caller_state() -> None:
    state = {"n": 0}

    def job() -> str:
        state["n"] += 1
        return str(state["n"])

    assert wrapped(job) == "start:1:end"
    assert wrapped(job) == "start:2:end"

